export class Economy {
  trade() {
    if (!this.trader || this.status !== 'playing' || !this.afford(this.trader.give)) return false;
    this.spend(this.trader.give);
    for (const [r, n] of Object.entries(this.trader.get)) this.resources[r] += n;
    this.notify('Trade complete', describeTrade(this.trader) + ' · done.', 'good');
    this.trader = null;
    this.traderTimer = 150 + this.random() * 120;
    return true;
  }
  dismissTrader() {
    if (!this.trader) return false;
    this.trader = null;
    this.traderTimer = 150 + this.random() * 120;
    return true;
  }

  // How much the stores are built to hold: a base stockpile plus each Storage Depot. Shown on the supplies
  // card; the simulation does not cap resources, so stock beyond it simply overflows the shelves.
  get storage() {
    const cap = { wood: 300, metal: 150, food: 250 };
    for (const b of this.buildings) if (b.type === 'storage') {
      const k = has(b, 'bulk_bins') ? 1.5 : 1;
      cap.wood += 200 * k; cap.metal += 100 * k; cap.food += 150 * k * (has(b, 'refrigeration') ? 1.2 : 1);
    }
    for (const r of ['wood', 'metal', 'food']) cap[r] = Math.round(cap[r]);
    return cap;
  }

  rates() {
    // A refuge's HQ salvages a trickle of wood; a camp only has the wood it fells. Scavenged metal comes in either way.
    const rates = { wood: this.buildings.some(b => b.type === 'core') ? .07 : 0, metal: .025, food: -this.survivors.length * T.food.perSurvivorPerSecond };
    for (const b of this.buildings) {
      if (b.type === 'farm') rates.food += .23 * (1 + (has(b, 'irrigation') ? .5 : 0) + (has(b, 'storage') ? .25 : 0) + (has(b, 'greenhouse') ? .75 : 0) + (has(b, 'harvest') ? .75 : 0)) * (this.night && !has(b, 'greenhouse') ? .4 : 1) * this.farmLabor(b);
      if (b.type === 'workshop') {
        rates.wood += .27 * (1 + (has(b, 'sawbench') ? .6 : 0) + (has(b, 'machinery') ? 1 : 0));
        rates.metal += .12 * (1 + (has(b, 'forge') ? .7 : 0) + (has(b, 'recycling') ? 1 : 0));
      }
      if (b.type === 'lumber_mill') {
        rates.wood += .35 * (1 + (has(b, 'circular_saw') ? .4 : 0) + (has(b, 'steam_engine') ? .7 : 0)) * this.loggerLabor(b);
      }
    }
    return rates;
  }
  // Farmers at work raise a farm's output; Intelligence makes them better at it.
  farmLabor(b) { return 1 + this.staffOf(b).filter(s => this.active(s) && !s.fighting).reduce((n, s) => n + T.farming.farmerBonus * statFactor(s.stats.int, T.effects.workPerIntelligence), 0); }
  // Loggers at work harvest wood at the sawmill / lumber mill; Strength speeds timber processing.
  loggerLabor(b) { return 1 + this.staffOf(b).filter(s => this.active(s) && !s.fighting).reduce((n, s) => n + .35 * statFactor(s.stats.str, T.effects.workPerIntelligence || .1), 0); }
  get dailyFoodDemand() { return this.survivors.length * T.food.perSurvivorPerSecond * DAY_SECONDS; }
  // Equipment: a shared stock of weapons, each reserved by at most one survivor.
  addItem(type) { const item = { id: this.nextId++, type, holder: null }; this.items.push(item); return item; }
  equip(s, item) {
    const old = s.weapon != null && this.items.find(i => i.id === s.weapon);
    if (old) old.holder = null;
    s.weapon = item ? item.id : null; s.gear = item ? item.type : null;
    if (item) item.holder = s.id;
  }
  // Hands out free gear by job preference. A survivor only swaps for something better,
  // so assignments stay stable between events.
  equipAll() {
    const rank = s => ({ sentry: 0, guard: 1, patrol: 2 }[s.role] ?? 3);
    for (const s of this.survivors.filter(s => !s.expedition && s.condition !== 'downed').sort((a, b) => rank(a) - rank(b) || a.id - b.id)) {
      const prefs = GEAR_PREFERENCE[jobOf(s)] || GEAR_PREFERENCE.default, score = type => type ? prefs.indexOf(type) : Infinity;
      const free = this.items.filter(i => i.holder == null).sort((a, b) => score(a.type) - score(b.type))[0];
      if (free && score(free.type) < score(s.gear)) this.equip(s, free);
    }
  }
  fabricate(type) {
    const weapon = WEAPONS[type];
    if (this.status !== 'playing' || !weapon?.cost || !this.buildings.some(b => b.type === 'workshop' || b.type === 'armory') || !this.spend(weapon.cost)) return false;
    this.addItem(type);
    this.equipAll();
    const holder = this.survivors.find(s => s.gear === type && this.items.find(i => i.id === s.weapon)?.id === this.items.at(-1).id);
    this.notify(weapon.name + ' made', holder ? holder.name + ' took it.' : 'It is in the stockpile.', 'good');
    return true;
  }
}

// Parties, departures and returns. Installed onto Game.prototype by model.mjs.
import { TUNING as T, WEAPONS, partyCap } from 'survivors.mjs';
import { HOUR_SECONDS, EXPEDITIONS, has } from 'data.mjs';
import { survivorStats } from 'rules.mjs';
import { POI_EXPEDITIONS } from 'worldgen.mjs';

export class Expeditions {
  get partyCap() { return partyCap(this.survivors.length); }
  findExpedition(kind) {
    if (EXPEDITIONS[kind]) return EXPEDITIONS[kind];
    if (POI_EXPEDITIONS[kind]) return POI_EXPEDITIONS[kind];
    if (kind && String(kind).startsWith('poi:')) {
      const id = parseInt(String(kind).slice(4), 10);
      const poi = this.worldPois?.find(p => p.id === id);
      if (poi && POI_EXPEDITIONS[poi.type]) {
        return { ...POI_EXPEDITIONS[poi.type], name: poi.name, poiId: id, targetX: poi.x, targetY: poi.y };
      }
    }
    return null;
  }
  // Why a survivor can't leave right now, or '' when they can.
  expeditionBlock(s, kind) {
    const trip = this.findExpedition(kind);
    if (this.status !== 'playing' || !s || !trip) return 'Unavailable';
    if (s.expedition) return 'Already away';
    if (s.condition === 'downed') return 'Downed';
    if (s.hp < survivorStats(s).hp * .5) return 'Too hurt to travel';
    if (s.shelter != null) return 'Sheltering';
    if (this.patrols.length < 2) return 'Someone must stay behind';
    if (!this.afford(trip.cost)) return 'Not enough supplies';
    return '';
  }
  partyCost(kind, size) {
    const trip = this.findExpedition(kind);
    return trip ? Object.fromEntries(Object.entries(trip.cost).map(([r, n]) => [r, n * size])) : {};
  }
  partyBlock(party, kind) {
    const trip = this.findExpedition(kind);
    if (!trip) return 'Unknown destination';
    if (!party.length) return 'Choose who goes';
    if (party.length > this.partyCap) return 'Party limit is ' + this.partyCap;
    if (new Set(party.map(s => s?.id)).size !== party.length) return 'Duplicate member';
    for (const s of party) { const block = this.expeditionBlock(s, kind); if (block) return (s?.name || 'Someone') + ': ' + block; }
    if (this.patrols.length - party.length < 1) return 'Someone must stay behind';
    if (!this.afford(this.partyCost(kind, party.length))) return 'Not enough supplies';
    return '';
  }
  expeditionRisk(kind, size = 1) {
    const trip = this.findExpedition(kind);
    const baseRisk = trip ? trip.risk : .2;
    return baseRisk * (this.clinic && has(this.clinic, 'surgeon') ? .6 : 1) * Math.max(.5, 1 - T.expedition.extraMemberRisk * (size - 1));
  }
  sendExpedition(ids, kind) {
    const party = [].concat(ids).map(id => this.survivors.find(s => s.id === id)), trip = this.findExpedition(kind);
    if (!trip || this.partyBlock(party, kind) || !this.spend(this.partyCost(kind, party.length))) return false;
    const total = trip.hours * HOUR_SECONDS, id = 'trip:' + this.nextEventId++;
    const targetX = trip.targetX != null ? trip.targetX : (this.worldPois?.length ? this.worldPois[0].x : 0);
    const targetY = trip.targetY != null ? trip.targetY : (this.worldPois?.length ? this.worldPois[0].y : 0);
    for (const s of party) {
      s.expedition = { kind, remaining: total, total, party: id, size: party.length, targetX, targetY, phase: 'traveling', startX: s.x, startY: s.y, poiId: trip.poiId };
      s.fighting = false; s.path = []; s.pathVersion = -1; this.dismount(s); s.goalKey = '';
      s.order = null; s.respond = null; s.care = null; s.careAt = null; s.shelter = null; s.sheltered = false; s.resting = false; s.restAt = null;
      this.releaseRescue(s);
      this.equip(s, null);
    }
    this.equipAll();
    this.notify(party.map(s => s.name).join(', ') + ' departed', trip.name + ' · back in about ' + trip.hours + ' game hours. Their posts are uncovered until then.', 'good');
    return true;
  }
  // The whole party returns together and shares one outcome roll per member.
  resolveExpeditions(dt) {
    const parties = new Map();
    for (const s of this.survivors) if (s.expedition) {
      s.expedition.remaining -= dt;
      const key = s.expedition.party || 'solo:' + s.id;
      parties.set(key, [...(parties.get(key) || []), s]);

      // Physical movement towards POI destination when on a world map
      if (this.map && s.expedition.targetX != null) {
        const trip = this.findExpedition(s.expedition.kind);
        const tripName = trip?.name || s.expedition.kind;
        const progress = Math.max(0, Math.min(1, 1 - (s.expedition.remaining / s.expedition.total)));
        if (progress < 0.35) {
          s.expedition.phase = 'traveling';
          const t = progress / 0.35;
          s.x = s.expedition.startX != null ? s.expedition.startX + (s.expedition.targetX - s.expedition.startX) * t : s.expedition.targetX * t;
          s.y = s.expedition.startY != null ? s.expedition.startY + (s.expedition.targetY - s.expedition.startY) * t : s.expedition.targetY * t;
          s.facing = s.expedition.targetX >= s.x ? 1 : -1;
          s.task = `Heading to ${tripName}`;
        } else if (progress < 0.70) {
          s.expedition.phase = 'scavenging';
          const wander = Math.sin((this.elapsed + s.id) * 2) * 12;
          s.x = s.expedition.targetX + wander;
          s.y = s.expedition.targetY + Math.cos((this.elapsed + s.id) * 2) * 8;
          s.facing = wander >= 0 ? 1 : -1;
          s.task = `Scavenging at ${tripName}`;
        } else {
          s.expedition.phase = 'returning';
          const t = (progress - 0.70) / 0.30;
          s.x = s.expedition.targetX * (1 - t);
          s.y = s.expedition.targetY * (1 - t);
          s.facing = 0 >= s.x ? 1 : -1;
          s.task = `Returning from ${tripName}`;
        }
      }
    }
    for (const members of parties.values()) {
      if (members.some(s => s.expedition.remaining > 0)) continue;
      const kind = members[0].expedition.kind, trip = this.findExpedition(kind), n = members.length, E = T.expedition;
      if (!trip) continue;
      if (trip.poiId != null && this.worldPois) {
        const poi = this.worldPois.find(p => p.id === trip.poiId);
        if (poi) poi.scavenged = true;
      }
      const carry = Math.max(.5, 1 + members.reduce((sum, s) => sum + (s.stats.str - 4) * T.effects.carryPerStrength, 0) / n);
      const loot = Object.fromEntries(Object.entries(trip.reward).map(([r, amount]) => [r, Math.round(amount * (1 + E.extraMemberReward * (n - 1)) * carry)]));
      for (const [r, amount] of Object.entries(loot)) this.resources[r] += amount;
      const risk = this.expeditionRisk(kind, n), lines = [Object.entries(loot).map(([r, amount]) => '+' + amount + ' ' + r).join(' · ')], lost = [];
      for (const s of members) {
        delete s.expedition;
        const [x, y] = this.safePatrolPosition(s.side); s.x = x; s.y = y;
        this.resetPatrol(s);
        const roll = this.random();
        if (roll < risk * E.deathShareOfRisk) { lost.push(s); continue; }
        if (roll < risk) { s.hp = Math.max(15, s.hp - E.injuryDamage); s.lastHit = this.elapsed; lines.push(s.name + ' was injured'); }
        this.grantXP(s, T.xp.expedition);
        this.updateCondition(s);
      }
      if (trip.weapon && this.random() < trip.weapon.chance) {
        const validTypes = (trip.weapon.types || []).filter(t => WEAPONS[t]);
        if (validTypes.length > 0) {
          const item = this.addItem(validTypes[Math.floor(this.random() * validTypes.length)]);
          if (item && WEAPONS[item.type]) lines.push('found a ' + WEAPONS[item.type].name.toLowerCase());
        }
      }
      if (this.random() < trip.rescueChance) { const c = this.createCandidate('expedition', trip.recruit.options, true, trip.recruit.label); lines.push('met ' + c.name + ', who wants to join'); }
      for (const s of lost) this.kill(s, 'Lost on the ' + trip.name.toLowerCase() + ' run.');
      this.equipAll();
      this.notify(members.map(s => s.name).join(', ') + (n > 1 ? ' are' : ' is') + ' back', lines.join('. ') + '.', lost.length || lines.some(l => l.includes('injured')) ? 'warn' : 'good');
    }
  }
}

// Felling trees for wood, from the design kit's Starter Camp. The player marks trees; the nearest
// free survivor walks out, chops, and carries the logs back to the camp's wood pile. A felled tree
// grows back after a minute or so of game time. Installed onto Game.prototype by model.mjs.
import { TUNING as T, statFactor } from 'survivors.mjs';
import { distance, has } from 'data.mjs';
import { CAMP, TREE_YIELD, TREE_NAMES, regrowSeconds, CHOP_SECONDS, CARRY_SPEED } from 'camp.mjs';

const HARVESTERS = new Set(['patrol', 'logger']);
export const treeKind = t => t.k || (t.kind === 2 ? 'tree_pine' : 'tree_oak');

export class Harvest {
  treeById(id) {
    const forest = this.forest;
    if (!forest.byId) forest.byId = new Map(forest.trees.map(t => [t.id, t]));
    return forest.byId.get(id) || null;
  }
  regrowing(t) { return (this.treeRegrow[t.id] || 0) > this.elapsed; }
  // Marks a tree for felling, or takes the mark off again. False for a tree still growing back.
  toggleHarvest(id) {
    const t = this.treeById(id);
    if (this.status !== 'playing' || !t || this.regrowing(t)) return false;
    const job = this.harvestJobs.find(j => j.tree === id);
    if (!job) { this.harvestJobs.push({ tree: id, by: null }); return true; }
    this.harvestJobs = this.harvestJobs.filter(j => j !== job);
    const s = this.survivors.find(s => s.id === job.by);
    if (s?.harvest?.tree === id) s.harvest = undefined;
    return true;
  }
  // Free to fell a tree: a patrol or logger on duty, fit, and not needed for anything more urgent.
  canHarvest(s) {
    return HARVESTERS.has(s.role || 'patrol') && !s.expedition && !s.sheltered && s.condition === 'healthy' && s.towerId == null && !s.order
      && s.shelter == null && s.rescue == null && !s.respond && !s.arriving && !this.alarm.raised && this.onDuty(s);
  }
  // Hands each marked tree to the nearest free survivor; loggers first. A survivor who is pulled
  // away before the tree is down gives it back.
  assignHarvest(dt) {
    this.harvestTimer = (this.harvestTimer || 0) - dt;
    if (this.harvestTimer > 0 || !this.harvestJobs.length) return;
    this.harvestTimer = .25;
    this.harvestJobs = this.harvestJobs.filter(j => this.treeById(j.tree));
    for (const job of this.harvestJobs) {
      const s = job.by != null && this.survivors.find(s => s.id === job.by);
      if (s && s.harvest?.tree === job.tree && s.hp > 0 && (s.harvest.phase === 'chop' || this.canHarvest(s))) continue;
      if (s && s.harvest?.tree === job.tree) s.harvest = undefined;
      job.by = null;
    }
    for (const job of this.harvestJobs) {
      if (job.by != null) continue;
      const t = this.treeById(job.tree);
      const pick = this.survivors.filter(s => !s.harvest && this.canHarvest(s)).sort((a, b) => (a.role === 'logger' ? 0 : 1) - (b.role === 'logger' ? 0 : 1) || distance(a, t) - distance(b, t))[0];
      if (!pick) break;
      job.by = pick.id;
      pick.harvest = { tree: job.tree, phase: 'toTree' };
      pick.path = []; pick.pathVersion = -1;
    }
  }
  // A standing spot beside the trunk, out of the other trunks, nearest `from`: off claimed land, or
  // on its walkable grid for a tree standing on a camp's own land.
  treeSpot(t, from) {
    const trees = this.forest.trees.filter(o => o !== t && distance(o, t) < 40);
    const spots = [];
    for (let i = 0; i < 8; i++) {
      const a = i * Math.PI / 4, p = { x: Math.round(t.x + Math.cos(a) * (t.radius + 7)), y: Math.round(t.y + Math.sin(a) * (t.radius + 7) * .7) };
      if (this.outside(p) && !this.wetAt(p)) spots.push(p);
    }
    for (let x = Math.round(t.x / 16) * 16 - 32; x <= t.x + 32; x += 16) for (let y = Math.round(t.y / 16) * 16 - 32; y <= t.y + 32; y += 16) {
      const p = { x, y }, d = distance(p, t);
      if (!this.outside(p) && d >= t.radius + 4 && d <= 28 && this.walkable(p)) spots.push(p);
    }
    let best = null, bestDistance = Infinity;
    for (const p of spots) {
      if (trees.some(o => distance(o, p) < o.radius + 5)) continue;
      const d = distance(p, from);
      if (d < bestDistance) { best = p; bestDistance = d; }
    }
    return best || { x: t.x, y: t.y + t.radius + 6 };
  }
  // Felled on a camp's own land, a tree is cleared for good; out in the wilds it grows back.
  clears(t) { return this.start === 'camp' && !this.outside(t); }
  // Where logs are dropped: the camp's wood pile, or beside the HQ in a refuge without one.
  get woodPile() { return this.buildings.some(b => b.type === 'campfire') ? CAMP.pile : null; }
  // Runs a survivor's felling job from work(). False when they have none.
  harvestWork(s, stats, dt) {
    const h = s.harvest;
    if (!h) return false;
    if (h.phase === 'toPile') {
      const pile = this.woodPile, spot = pile ? { x: pile.x, y: pile.y + 16 } : this.core && this.goalFor(s, this.core);
      if (!spot || this.travel(s, spot, stats.speed * CARRY_SPEED, dt)) {
        this.resources.wood += h.carry;
        const at = pile || s;
        this.effects.push({ type: 'wood', x: at.x, y: at.y - 14, amount: h.carry, life: 1.4, maxLife: 1.4 });
        s.harvest = undefined;
        s.task = 'stacking-wood';
      } else s.task = 'carrying-wood';
      return true;
    }
    const t = this.treeById(h.tree), job = this.harvestJobs.find(j => j.tree === h.tree && j.by === s.id);
    if (!t || !job) { s.harvest = undefined; return false; }
    if (h.phase === 'toTree') {
      if (!h.spot) h.spot = this.treeSpot(t, s);
      if (!this.travel(s, h.spot, stats.speed, dt)) { s.task = 'to-tree'; return true; }
      Object.assign(h, { phase: 'chop', left: CHOP_SECONDS, swing: 0 });
    }
    // Chopping: Strength speeds it, and so does a lumber mill's log chute for its loggers.
    const post = this.postOf(s), speed = statFactor(s.stats.str, T.effects.workPerIntelligence) * (post && has(post, 'log_chute') ? 1.3 : 1);
    h.left -= dt * speed;
    s.task = 'chopping';
    s.facing = t.x < s.x ? -1 : 1;
    const swing = Math.floor((CHOP_SECONDS - h.left) * 2.2);
    if (swing !== h.swing) { h.swing = swing; this.effects.push({ type: 'chip', x: t.x, y: t.y - 8, life: .5, maxLife: .5 }); }
    if (h.left > 0) return true;
    const k = treeKind(t);
    if (this.clears(t)) { this.cleared.push(t.id); this.landRevision++; } else this.treeRegrow[t.id] = this.elapsed + regrowSeconds(k);
    this.harvestJobs = this.harvestJobs.filter(j => j !== job);
    if (this.progress) this.progress.tally.felled++;
    this.grantXP(s, T.xp.dutyPerSecond * 30);
    s.harvest = { phase: 'toPile', carry: Math.round((TREE_YIELD[k] || 4) * statFactor(s.stats.str, T.effects.carryPerStrength)) };
    s.path = []; s.pathVersion = -1;
    return true;
  }
  // What the view draws over the trees: marks, regrowth, who is chopping and who carries logs.
  harvestView() {
    const out = { jobs: [], regrow: [], chopping: [], carrying: [], pile: this.woodPile };
    for (const j of this.harvestJobs) { const t = this.treeById(j.tree); if (t) out.jobs.push({ id: t.id, x: t.x, y: t.y, assigned: j.by != null }); }
    for (const [id, end] of Object.entries(this.treeRegrow)) {
      const t = end > this.elapsed && this.treeById(id);
      if (t) out.regrow.push({ id, x: t.x, y: t.y, f: 1 - (end - this.elapsed) / regrowSeconds(treeKind(t)) });
    }
    for (const s of this.survivors) {
      if (s.harvest?.phase === 'chop') out.chopping.push({ tree: s.harvest.tree, survivor: s.id, swing: (CHOP_SECONDS - s.harvest.left) * 2.2 % 1 });
      if (s.harvest?.phase === 'toPile') out.carrying.push(s.id);
    }
    return out;
  }
  // A line for hovering a tree.
  treeHint(id) {
    const t = this.treeById(id);
    if (!t) return '';
    const k = treeKind(t), left = Math.ceil((this.treeRegrow[id] || 0) - this.elapsed), job = this.harvestJobs.find(j => j.tree === id);
    const who = job?.by != null && this.survivors.find(s => s.id === job.by);
    return `${TREE_NAMES[k]} · ${TREE_YIELD[k]} wood · ` + (left > 0 ? `growing back, ${left}s` : job ? (who ? `${who.name} is on it · click to cancel` : 'marked · click to cancel') : this.clears(t) ? 'click to clear for good' : 'click to fell');
  }
}

// healthy → injured → downed → dead, rescues and clinic care. Installed onto Game.prototype by model.mjs.
import { TUNING as T, statFactor } from 'survivors.mjs';
import { HOUR_SECONDS, distance, has } from 'data.mjs';
import { survivorStats } from 'rules.mjs';

export class Health {
  // ---- Health: healthy → injured → downed → dead ----
  active(s) { return !s.expedition && s.condition !== 'downed' && !s.sheltered; }
  sceneSafe(p) { return !this.zombiesNear(p, T.health.safeRadius).some(z => z.hp > 0 && distance(z, p) < T.health.safeRadius); }
  updateCondition(s, max = survivorStats(s).hp) {
    if (s.condition === 'downed') return;
    s.condition = s.hp < max * T.health.injuryThreshold ? 'injured' : 'healthy';
  }
  down(s) {
    this.releaseRescue(s);
    Object.assign(s, { hp: 0, condition: 'downed', bleed: T.health.bleedOutHours * HOUR_SECONDS * statFactor(s.stats.end, T.effects.bleedPerEndurance), stabilize: 0, stabilizing: false, rescuer: null });
    Object.assign(s, { stationed: false, perch: null, towerId: null, goalKey: '', care: null, careAt: null, order: null, respond: null, sheltered: false, resting: false, restAt: null, fighting: false, path: [] });
    this.notify(s.name + ' is down', 'About ' + (s.bleed / HOUR_SECONDS).toFixed(1) + ' game hours to bleed out unless someone stabilizes them.', 'warn');
  }
  releaseRescue(s) {
    if (s.rescue == null) return;
    const patient = this.survivors.find(x => x.id === s.rescue);
