        const next = steerAroundTrees(this.forest, s, { x: (p.x - s.x) / d, y: (p.y - s.y) / d }, movement, 4, s.id % 2 ? 1 : -1);
        s.x = next.x; s.y = next.y;
      } else { s.x += (p.x - s.x) / d * movement; s.y += (p.y - s.y) / d * movement; }
