    type: p.type,
    label: p.label || POI_TYPES[p.type]?.label || p.type,
    name: p.name || (p.label + ' ' + (p.id + 1)),
    x: Math.round((p.x - bcx) * 16),
    y: Math.round((p.y - bcy) * 16),
    r: Math.round((p.r || 6) * 16),
    tx: Math.round(p.x),
    ty: Math.round(p.y),
    scavenged: false,
    blds: (p.blds || []).map(b => ({
      k: b.k,
      tx: b.tx,
      ty: b.ty,
      x: Math.round((b.tx - bcx) * 16),
      y: Math.round((b.ty - bcy) * 16)
    }))
  }));

