    const y = Math.round((o.ty - bcy) * 16);
    if (campProp(o)) return;
    if (o.t === 'bridge') {
      worldDecor.push({ key: 'tiles/' + o.k, k: o.k, tx: o.tx, ty: o.ty, px: x + 8, py: y + 8, bridge: true, ...propPlacement(o, x, y) });
    } else if (o.t === 'bld' && o.k && o.k.startsWith('wld_')) {
