    x: Math.max(bcx, map.w - bcx) * 16 + 128,
    y: Math.max(bcy, map.h - bcy) * 16 + 128,
    width: map.w * 16,
    height: map.h * 16,
    left: -bcx * 16,
    right: (map.w - bcx) * 16,
    top: -bcy * 16,
    bottom: (map.h - bcy) * 16
