  }
  const walk = [];
  for (const p of pois) {
    if (p.type !== 'town') continue;
    for (let y = p.y - p.r - 3; y <= p.y + p.r + 3; y++) for (let x = p.x - p.r - 3; x <= p.x + p.r + 3; x++) {
